using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class BetaTests {
 static int checks,failures;
 static void Check(bool ok,string label){checks++;if(!ok){failures++;Console.WriteLine("FAIL Beta: "+label);}}
 static void Call(object o,string method,params object[] args){o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static Franchise Club(){return Franchise.Create(new Profile(),new Roster());}
 static Simulation Pass(float x,float z){Simulation s=new Simulation(912);s.Practice=true;s.NewGame();s.Snap();for(int i=0;i<20;i++)s.Update(.025f,0,0);s.BeginPass(0);s.Charge=.35f;s.PlacementX=x;s.PlacementZ=z;s.ReleasePass();return s;}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride;string folder=Path.Combine(Path.GetTempPath(),"Downfield-beta-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Simulation center=Pass(0,0),lead=Pass(1.75f,2),cap=Pass(100,100),away=Pass(-1.75f,-2);
  Check(Math.Abs(lead.FlightTargetX-center.FlightTargetX-1.75f)<.001f,"left stick moves horizontal placement only slightly");
  Check(Math.Abs(lead.FlightTargetZ-center.FlightTargetZ-2)<.001f,"up stick leads two yards");
  Check(Math.Abs(cap.FlightTargetX-lead.FlightTargetX)<.001f&&Math.Abs(cap.FlightTargetZ-lead.FlightTargetZ)<.001f,"placement cannot exceed cap");
  Check(away.FlightTargetX<center.FlightTargetX&&away.FlightTargetZ<center.FlightTargetZ,"placement works both directions");
  Check(lead.State==Phase.Flight&&!lead.Controlled.HasBall,"placement releases a real football");
  foreach(bool receives in new bool[]{false,true}){Simulation s=new Simulation(3);s.Quarter=2;s.Clock=0;s.Spot=76;s.Down=3;s.FirstDown=82;s.Timeouts=0;s.SecondHalfOpponent=receives;Call(s,"CheckQuarter");Check(s.State==Phase.Halftime&&s.Quarter==3&&s.Clock==60,"halftime stops clock and waits for player");Check(s.Spot==20&&s.Down==1&&s.FirstDown==30&&s.Timeouts==3,"halftime resets field and timeouts");s.Update(.05f,0,1);Check(s.State==Phase.Halftime&&s.HalftimeCount==1,"halftime never auto resumes old possession");s.BeginSecondHalf();Check(s.State==(receives?Phase.Opponent:Phase.PreSnap)&&s.Spot==20,"second half receives at own 20");if(receives){s.Next();for(int i=0;i<60;i++)s.Update(.05f,0,0);Check(s.AwayScore>=0&&s.Spot==20,"opponent kickoff drive resolves normally");}}
  Simulation end=new Simulation(17);end.Quarter=2;end.Clock=0;Call(end,"ScoreTouchdown");Check(end.State==Phase.Conversion,"end half TD gets conversion");end.ChooseConversion(false);end.KickMeter=.5f;end.StopKick();for(int i=0;i<80;i++)end.Update(.05f,0,0);Check(end.State==Phase.Halftime&&end.HomeScore>=6,"halftime follows untimed PAT");
  Simulation option=new Simulation(23);option.Practice=true;option.Playbook=22;option.RunPlay=true;option.NewGame();option.Snap();Check(option.OptionLive&&!option.CanThrow&&!option.HandoffPending,"option starts as give or keep");option.GiveOption();for(int i=0;i<15;i++)option.Update(.04f,0,0);Check(option.Controlled.Role=="RB"&&option.OptionGiven&&option.Rushes==1,"option give hands off once");
  option=new Simulation(23);option.Practice=true;option.Playbook=22;option.RunPlay=true;option.NewGame();option.Snap();for(int i=0;i<45;i++)option.Update(.05f,0,1);Check(option.Controlled.Role=="QB"&&option.Controlled.Z>option.Spot,"option keep lets QB run");option.GiveOption();Check(!option.HandoffPending,"give unavailable past LOS");
  Simulation jet=new Simulation(9);jet.Practice=true;jet.Playbook=21;jet.RunPlay=true;jet.NewGame();jet.Snap();for(int i=0;i<14;i++)jet.Update(.04f,0,0);Check(jet.Controlled==jet.Players[10],"jet sweep gives slot receiver the ball");
  Check(Simulation.SkillSpeed("WR",99)-Simulation.SkillSpeed("CB",70)>3.3f,"elite speed creates a large rating gap");Franchise f=Club();f.Starter(0,2).Speed=99;f.Starter(1,15).Speed=70;Simulation rated=new Simulation(9);f.Apply(rated,1);rated.NewGame();Check(rated.Players[2].Speed>rated.Players[15].Speed+3,"roster speed differences reach simulation");
  rated.Controlled.Z=rated.Spot+3;rated.Players[2].X=0;rated.Players[2].Z=rated.Spot+8;rated.Players[15].X=0;rated.Players[15].Z=rated.Spot+9;rated.State=Phase.Live;Check((bool)typeof(Simulation).GetMethod("EligibleBlocker",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(rated,new object[]{rated.Players[2]}),"WR becomes blocker after QB crosses line");
  for(int i=11;i<rated.Players.Count;i++){rated.Players[i].X=60;rated.Players[i].Z=60;}rated.Players[15].X=rated.Players[2].X;rated.Players[15].Z=rated.Players[2].Z+1;Call(rated,"ResolveLineContacts",.016f);Check(rated.Players[2].BlockPartner==15&&rated.Players[15].BlockPartner==2,"WR actually engages downfield defender for scrambling QB");
  int lowCatch=0,highCatch=0;for(int seed=0;seed<200;seed++)for(int tier=0;tier<2;tier++){Simulation hands=new Simulation(4000+seed);hands.Practice=true;hands.NewGame();hands.Receiver(0).Hands=tier==0?70:99;hands.Snap();for(int t=0;t<20;t++)hands.Update(.025f,0,0);hands.BeginPass(0);hands.Charge=.35f;hands.ReleasePass();for(int t=0;t<100&&hands.State==Phase.Flight;t++)hands.Update(.025f,0,0);if(hands.Completions>0){if(tier==0)lowCatch++;else highCatch++;}}Console.WriteLine("Hands ratings: 70 = "+lowCatch+" / 200, 99 = "+highCatch+" / 200 matched open throws");Check(highCatch>lowCatch+20,"elite hands catch materially more matched throws");
  DrawnPlay play=new DrawnPlay();DrawnRoute route=new DrawnRoute();route.Receiver=0;route.Points.Add(new RouteNode(-19,8));route.Points.Add(new RouteNode(5,8));play.Routes.Add(route);DrawnPlay copy=play.Copy();copy.Routes[0].Points[0].X=22;Check(play.Routes[0].Points[0].X==-19,"custom play copy is isolated");Simulation drawn=new Simulation(5);drawn.Practice=true;drawn.CustomPlay=play;drawn.UseCustom=true;float[] point=drawn.GetRoutePoint(drawn.Receiver(0),2);Check(point[0]>-19&&Math.Abs(point[1]-drawn.Spot-8)<.01f,"custom receiver follows drawn cut");drawn.Snap();for(int i=0;i<50;i++)drawn.Update(.05f,0,0);Check(drawn.Receiver(0).X>-17,"custom route moves player on field");drawn.CyclePlay(1);drawn.State=Phase.PreSnap;drawn.CyclePlay(1);Check(!drawn.UseCustom,"stock call exits custom play");
  f=Club();f.NameCoach("  Danny  ");f.Coach.Skin=3;f.Coach.Hair=2;f.Coach.Hat=2;f.Coach.Outfit=5;f.SavedPlay=play;f.Save();Franchise reload=Franchise.Load(new Profile(),new Roster());Check(reload.Coach.Name=="DANNY"&&reload.Coach.Skin==3&&reload.Coach.Outfit==5,"coach name and pixel appearance save");Check(reload.SavedPlay.Routes[0].Points[1].X==5,"custom routes survive save load");
  int first=f.UserGame.Id;f.FinishGame(first,35,7);Check(f.Coach.Wins==1&&f.Coach.Losses==0,"career records result once");f.FinishGame(first,35,7);Check(f.Coach.Wins==1,"duplicate result does not inflate career");Check(f.Production.Exists(p=>p.Team!=f.UserTeam)&&f.Production.Exists(p=>p.Team==f.UserTeam),"simulated and CPU games produce award stats");
  while(!f.Complete){if(f.UserGame==null)f.Advance();else f.FinishGame(f.UserGame.Id,49,0);}
  Check(f.Coach.Wins==13&&f.Coach.PlayoffWins==2&&f.Coach.Championships==1&&f.Coach.WinPercent==100,"coach counts regular wins playoff wins and title");Check(f.History.Count==12&&f.History.FindAll(h=>h.Champion).Count==1,"season archives all clubs and one champion");Check(f.Awards.FindAll(a=>a.Type=="CHAMPIONSHIP").Count==1&&f.Awards.FindAll(a=>a.Type=="MVP").Count==1&&f.Awards.FindAll(a=>a.Type=="OPOTY").Count==1,"championship MVP and OPOTY awarded");int won=f.Coach.Wins;Check(f.JoinClub(1)&&f.Coach.Wins==won&&f.Coach.Name=="DANNY","coach record follows new club in offseason");f.NextSeason();Check(f.History.Count==12&&f.Awards.Count==3&&f.Production.Count==0,"next season preserves history and clears current stats");f.FinishGame(f.UserGame.Id,0,35);Check(f.Coach.Wins==won&&f.Coach.Losses==1&&f.Coach.WinPercent<100,"new team result joins same career");Check(!f.JoinClub(2),"in season club switch blocked");f.Save();reload=Franchise.Load(new Profile(),new Roster());Check(reload.Coach.Wins==won&&reload.History.Count==12&&reload.Awards.Count==3,"career awards and history reload");
  Franchise legacy=Club();legacy.Coach=new CoachRecord();Fixture oldGame=legacy.Games[0];oldGame.Home=legacy.UserTeam;oldGame.Away=1;oldGame.HomeScore=21;oldGame.AwayScore=7;oldGame.Played=true;legacy.Titles=2;legacy.EnsureCareer();legacy.EnsureCareer();Check(legacy.Coach.Wins==1&&legacy.Coach.Championships==2,"legacy save migrates available records once");
  foreach(string cue in new string[]{"snap","hit","score","jump","halftime"}){byte[] wave=GameAudio.CreateWave(cue);Check(System.Text.Encoding.ASCII.GetString(wave,0,4)=="RIFF"&&System.Text.Encoding.ASCII.GetString(wave,8,4)=="WAVE"&&BitConverter.ToInt32(wave,4)==wave.Length-8,"valid original sound "+cue);}using(GameAudio sound=new GameAudio()){sound.Play("hit");sound.Muted=true;sound.Play("score");Check(sound.LastCue=="score"&&sound.Played==2,"sound cues and mute handle safely");}
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}Console.WriteLine("Beta: "+checks+" checks, "+failures+" failures");return failures;}
}
}
